  const foreignJournalText = `${JSON.stringify({
    targetPath: configPath,
    createdFile: false,
    generation: 'c0ffee00-0000-4000-8000-000000000160',
    publishGeneration: 'c0ffee00-0000-4000-8000-000000000161',
  })}\n`
