test('A refresh whose old record goes back while a backup restores the config it covers answers current on the config it reads after that put-back', async (context) => {
  // Value: protects=a refresh decides the rest of its run on the config as it stands after the old record went back, so a config restored meanwhile that the old record owns is reconnected in that same run; fails_when=the refresh answers anything but current, receipt.json holds anything but the old record, a record stays, or the restored config changes; no_claim=a real backup tool (the config module is loaded with a link that moves the old config back right after the put-back's link), a real process end (seam.afterPublish throws) and why the private name's unlink failed in that setup (unlink stub EBUSY)
  // Arrange
  const {
    home,
    storage,
    configPath,
    receiptPath,
    receiptBefore,
    oldConfigText,
    moveBack,
  } = await arrangeMovedAwayConfig(context)
  const busyRetiredName = await loadModule<typeof DevinMcpConfigModule>(
    resolve(__dirname, '../devinMcpConfig.js'),
    {
      'node:fs/promises': {
        link,
        lstat,
        mkdir,
        open,
        rename,
        rm,
        unlink: async (path: string) => {
          if (path.endsWith('.retired'))
            throw Object.assign(new Error('busy'), { code: 'EBUSY' })
          return unlink(path)
        },
      },
    },
    { Error, TextDecoder },
  )
  await assert.rejects(
    busyRetiredName.writeManagedDevinMcpEntry(storage, ENTRY, home, {
      afterPublish: () => {
        throw new Error('process ended')
      },
    }),
    /process ended/,
  )
  // The config the stopped setup published is gone before the next run looks.
  rmSync(configPath)
  let hasRestored = false
  const restoringBackup = await loadModule<typeof DevinMcpConfigModule>(
    resolve(__dirname, '../devinMcpConfig.js'),
    {
      'node:fs/promises': {
        link: async (from: string, to: string) => {
          await link(from, to)
          // A backup tool restores the old config right after the old record went back.
          if (to === receiptPath && !hasRestored) {
            hasRestored = true
            moveBack()
          }
        },
        lstat,
        mkdir,
        open,
        rename,
        rm,
        unlink,
      },
    },
    { Error, TextDecoder },
  )

  // Act
  const result = await restoringBackup
    .refreshManagedDevinMcpEntry(storage, ENTRY, home)
    .then(
      ({ status }) => status,
      (error: unknown) => error,
    )

  // Assert
  assert.equal(hasRestored, true)
  assert.equal(result, 'current')
  assert.deepEqual(await readRecordFile(storage, 'receipt.json'), receiptBefore)
  assert.deepEqual(await recordsIn(storage), ['receipt.json'])
  assert.equal(readFileSync(configPath, 'utf8'), oldConfigText)
})

test('A first setup that linked nothing gets its old record back even when the restored config has the inode it had staged', async (context) => {
  // Value: protects=a publish known never to have linked puts its old record back and takes nothing back, whatever inode the config shows; fails_when=the record lacks the mark, the old record is gone, the restored entry is taken out, or the setup answers anything but current; no_claim=a real inode reuse (the test writes the config's inode into stagedIno), why the put-back failed (link stub EIO)
  // Arrange
  const {
    home,
    storage,
    configPath,
    receiptPath,
    receiptBefore,
    oldConfigText,
    moveBack,
  } = await arrangeMovedAwayConfig(context)
  const failingPutBack = await loadModule<typeof DevinMcpConfigModule>(
    resolve(__dirname, '../devinMcpConfig.js'),
    {
      'node:fs/promises': {
        link: async (from: string, to: string) => {
          if (to === receiptPath)
            throw Object.assign(new Error('i/o error'), { code: 'EIO' })
          return link(from, to)
        },
        lstat,
        mkdir,
        open,
        rename,
        rm,
        unlink,
      },
    },
    { Error, TextDecoder },
  )
  await assert.rejects(
    failingPutBack.writeManagedDevinMcpEntry(storage, ENTRY, home, {
      afterCheck: moveBack,
    }),
    /could not put it back/,
  )
  const recordAfterRefusal = await readRecordFile(storage, 'pending.json')
  // The restored config shows the inode the setup had staged, as a freed inode number used again does.
  await writeRecordFile(storage, 'pending.json', {
    ...recordAfterRefusal,
    stagedIno: statSync(configPath).ino,
  })

  // Act
  const next = await writeManagedDevinMcpEntry(storage, ENTRY, home).then(
    (result) => result.status,
    (error: unknown) => error,
  )

  // Assert
  assert.equal(recordAfterRefusal.notLinked, true)
  assert.equal(next, 'current')
  assert.deepEqual(await readRecordFile(storage, 'receipt.json'), receiptBefore)
  assert.equal(readFileSync(configPath, 'utf8'), oldConfigText)
  assert.deepEqual(await recordsIn(storage), ['receipt.json'])
})

test("A setup that keeps another program's file at the old record's private name, with nothing at receipt.json, writes its publish record so that Codebook 0.2.143.0 refuses it before it would put that file back, and this version still reads it", async (context) => {
  // Value: protects=once a setup kept a file at the private name that is no record of this config while nothing stands at receipt.json, its publish record carries retiresReceipt in this version's form, which names the old record's bytes from its first write on, which 0.2.143.0's reader refuses as unreadable before it links whatever stands at that name into receipt.json (its put-back of a notLinked record), while this version still reads that record, keeps that file and asks again to move it (Cycle 0148 ship review); fails_when=the record lacks that form or the notLinked mark, 0.2.143.0's field rules accept it, a file appears at receipt.json, the file at the private name changes or is gone, or either setup answers another sentence; no_claim=0.2.143.0 itself (the test checks the record against that build's field rules, RELEASED_PUT_BACK_FIELDS, read from its code), a real sync tool (the config module is loaded with a link that, for the config's link, moves the old config back and then puts another program's file at the private name at another inode)
  // Arrange
  const { home, storage, configPath, receiptPath, receiptBefore, moveBack } =
    await arrangeMovedAwayConfig(context)
  const pendingPath = join(storage, 'devin-mcp', 'pending.json')
  const recordsFolder = join(storage, 'devin-mcp')
  const otherProgramText = '{"note":"a settings file of another program"}'
  let retiredName = 'no private name'
  const swappingAtLink = await loadModule<typeof DevinMcpConfigModule>(
    resolve(__dirname, '../devinMcpConfig.js'),
    {
      'node:fs/promises': {
        link: async (from: string, to: string) => {
          if (to === configPath) {
            // The old config comes back, so the link fails, and another program's file takes the old record's private name.
            moveBack()
            retiredName =
              readdirSync(recordsFolder).find((name) =>
                name.endsWith('.retired'),
              ) ?? retiredName
            swapFile(join(recordsFolder, retiredName), otherProgramText)
          }
          return link(from, to)
        },
        lstat,
        mkdir,
        open,
        rename,
        rm,
        unlink,
      },
    },
    { Error, TextDecoder },
  )

  // Act
  const setupError = await swappingAtLink
    .writeManagedDevinMcpEntry(storage, ENTRY, home)
    .then(
      () => undefined,
      (error: unknown) => error,
    )
  const recordAfterRefusal = existsSync(pendingPath)
    ? JSON.parse(readFileSync(pendingPath, 'utf8'))
    : 'absent'
  const recordsAfterRefusal = await recordsIn(storage)
  const nextError = await writeManagedDevinMcpEntry(storage, ENTRY, home).then(
    () => undefined,
    (error: unknown) => error,
  )

  // Assert
  const retiredPath = join(recordsFolder, retiredName)
  const keptSentence = `Codebook did not put back the file at ${retiredPath}, where it had moved what stood at ${receiptPath} for a setup, because that file is no record of Devin Desktop's MCP config at ${configPath} (another program may have put it there); it kept that file and its publish record at ${pendingPath}, so move that file to another folder, then run Codebook: Set Up AI Chat again. Unless a record of Codebook's stands at ${receiptPath} by then, that run takes a "codebook" entry that the config holds for one of your own and leaves it as it is.`
  assert.equal(
    setupError instanceof Error ? setupError.message : setupError,
    `Codebook found a file that changed while Codebook was working on it in Devin Desktop's MCP config at ${configPath} and left that file untouched; look at the file, then run Codebook: Set Up AI Chat again. ${keptSentence}`,
  )
  assert.deepEqual(recordsAfterRefusal, ['pending.json', retiredName])
  assert.deepEqual(recordAfterRefusal.retiresReceipt, {
    sha256: sha256(JSON.stringify(receiptBefore)),
  })
  assert.equal(recordAfterRefusal.notLinked, true)
  assert.equal(
    RELEASED_PUT_BACK_FIELDS.safeParse(recordAfterRefusal).success,
    false,
  )
  assert.equal(
    nextError instanceof Error ? nextError.message : nextError,
    keptSentence,
  )
  assert.deepEqual(await recordsIn(storage), ['pending.json', retiredName])
  assert.equal(readFileSync(retiredPath, 'utf8'), otherProgramText)
})

